.wb-body{padding:12px 4px 2px;height:100%;box-sizing:border-box;font-family:'Poppins','Segoe UI',Arial,sans-serif;color:#1a1a1a;display:flex;flex-direction:column;gap:9px;overflow:hidden;}
.wb-note{border:2px dashed #E2571C;border-radius:8px;padding:9px 13px;background:#fff8f3;font-size:13.5px;line-height:1.45;}
.wb-note b{color:#E2571C;}
.wb-worked{border:2px solid #F5A623;border-radius:8px;padding:9px 13px;background:#fffaf0;font-size:13.5px;line-height:1.45;font-weight:600;color:#1a1a2e;}
.wb-lbl{font-size:11px;font-weight:800;color:#c45a12;text-transform:uppercase;letter-spacing:0.8px;margin-bottom:-4px;}
.wb-exwrap{display:flex;flex-direction:column;gap:3px;}
.wb-exitem{font-size:13.5px;font-weight:600;color:#1a1a1a;}
.wb-blank{border-bottom:1.6px solid #999;height:16px;margin-top:2px;}
.wb-challenge{border:2px solid #E2571C;border-radius:10px;padding:9px 13px;background:#fff;}
.wb-challenge .wb-clabel{font-weight:800;color:#E2571C;font-size:11px;text-transform:uppercase;letter-spacing:0.8px;margin-bottom:3px;}
.wb-challenge .wb-ctext{font-size:13.5px;font-weight:600;}
.wb-tablewrap{border:2px solid #E2571C;border-radius:8px;overflow:hidden;}
.wb-table{width:100%;border-collapse:collapse;font-size:13px;}
.wb-table th{background:#E2571C;color:#fff;padding:6px 10px;font-weight:700;text-align:left;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.wb-table td{padding:6px 10px;border-top:1px solid #f0c9a8;border-right:1px solid #f0c9a8;font-weight:600;}
.wb-table td:last-child,.wb-table th:last-child{border-right:none;}
.wb-table td.blankcell{color:#ccc;}
.wb-scoretable td:nth-child(2){text-align:center;font-weight:800;color:#E2571C;}
.wb-scoretable tr.wb-total td{background:#fff8f3;font-weight:800;}
.wb-fillline{border-bottom:1.6px solid #999;flex:1;display:inline-block;margin-left:6px;height:14px;}
.wb-promptrow{font-size:13px;font-weight:600;display:flex;align-items:baseline;gap:0;}
.wb-passage{border:2px dashed #E2571C;border-radius:8px;padding:10px 14px;background:#fff8f3;font-size:14px;line-height:1.55;font-style:italic;color:#1a1a1a;}
.wb-instr{border:2px solid #F5A623;border-radius:8px;padding:8px 12px;background:#fffaf0;font-size:12.5px;font-weight:700;color:#1a1a2e;line-height:1.4;}
.wb-titlepage{font-family:'Times New Roman',Times,serif;text-align:center;padding:26px 46px 10px;height:100%;box-sizing:border-box;display:flex;flex-direction:column;justify-content:center;}
.wb-tp-line{width:90px;height:3px;background:#F5A623;margin:14px auto;border-radius:2px;}
.wb-tp-title{font-size:32px;font-weight:800;color:#1a1a2e;letter-spacing:1px;}
.wb-tp-subtitle{font-size:16px;color:#E2571C;font-style:italic;margin-top:6px;}
.wb-tp-edition{font-size:12px;font-weight:800;color:#c45a12;text-transform:uppercase;letter-spacing:1.4px;margin-top:16px;}
.wb-tp-keywords{font-size:11.5px;color:#6c757d;margin-top:8px;line-height:1.5;padding:0 10px;}
.wb-tp-fields{margin-top:22px;text-align:left;font-size:14.5px;font-weight:600;font-family:'Poppins','Segoe UI',Arial,sans-serif;}
.wb-tp-fields .fld{margin-bottom:20px;border-bottom:1.6px solid #999;padding-bottom:5px;color:#1a1a1a;}
.wb-tp-fields .fldrow{display:flex;gap:24px;}
.wb-tp-fields .fldrow .fld{flex:1;}
.wb-tp-note{margin-top:20px;font-size:12px;color:#6c757d;font-style:italic;line-height:1.55;font-family:'Poppins','Segoe UI',Arial,sans-serif;}
.wb-toc{font-family:'Times New Roman',Times,serif;padding:6px 4px;height:100%;box-sizing:border-box;}
.wb-toc-title{font-size:22px;font-weight:800;color:#1a1a2e;text-align:center;border-bottom:4px solid #F5A623;padding-bottom:9px;margin-bottom:6px;}
